select null, t.id, 'builtin', 'For PT and aPTT, blood is drawn into a 3.2% sodium citrate (light blue) tube at a blood-to-citrate ratio of:', '["1:1","4:1","9:1","1:9"]'::jsonb, 2, 'Citrate binds calcium to keep the sample from clotting. The tube must be filled to at least 90% so the 9:1 blood-to-citrate ratio is kept; underfilling falsely prolongs results, especially the aPTT. Reference: StatPearls, Prothrombin Time (ncbi.nlm.nih.gov/books/NBK544269).', '["Too much citrate for the blood; the tube would be badly underfilled.","Not the standard ratio.","Nine parts blood to one part citrate; underfilling falsely prolongs clotting times.","Reversed: one part blood to nine parts citrate."]'::jsonb, 2, 'verified'
