insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'In a healthy adult, red blood cells are produced in the:', '["Yolk sac","Liver","Spleen","Bone marrow"]'::jsonb, 3, 'Hematopoiesis starts in the yolk sac, shifts to the fetal liver (and spleen), and the bone marrow takes over near the end of gestation. In adults it normally occurs only in the bone marrow. Reference: StatPearls, Embryology, Hematopoiesis (ncbi.nlm.nih.gov/books/NBK544245).', '["Blood formation site only in the early embryo.","Main site in mid-fetal life; in adults only in disease (extramedullary).","Fetal site; in adults only in disease.","In adults: flat bones (pelvis, sternum, vertebrae) and the ends of long bones."]'::jsonb, 1, 'verified'
