select null, t.id, 'builtin', 'The first site of blood cell formation in the embryo is the:', '["Liver","Yolk sac","Spleen","Bone marrow"]'::jsonb, 1, 'Blood formation starts in the extraembryonic yolk sac; stem cells then seed the fetal liver (and spleen) before the bone marrow takes over. Reference: Lawrence et al., The Ontogeny of a Neutrophil: Mechanisms of Granulopoiesis and Homeostasis (pmc.ncbi.nlm.nih.gov/articles/PMC5813886).', '["Takes over in the second trimester.","Blood islands form in the yolk sac in the first weeks.","A later fetal site, after the liver.","Main site from the late fetal period onward."]'::jsonb, 1, 'verified'
