select null, t.id, 'builtin', 'Rouleaux formation on a blood smear is associated with:', '["Iron deficiency anemia","Sickle cell anemia","Hereditary elliptocytosis","Multiple myeloma"]'::jsonb, 3, 'Rouleaux (red cells stacked like coins) suggest a paraproteinemia or plasma cell dyscrasia such as multiple myeloma. Reference: Peripheral Blood Film: A Review, Ann Ib Postgrad Med 2014 (pmc.ncbi.nlm.nih.gov/articles/PMC4415389).', '["Microcytic, hypochromic cells; no rouleaux.","Sickle cells do not stack.","Shows elliptocytes.","High monoclonal protein makes red cells stack like coins."]'::jsonb, 1, 'verified'
