insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Anemia of chronic inflammation typically shows:', '["Low iron, high TIBC, low ferritin","Low iron, low TIBC, normal or high ferritin","High iron, low TIBC, high ferritin","Normal iron, high TIBC, low ferritin"]'::jsonb, 1, 'Anemia of chronic disease shows low serum iron with decreased TIBC, while ferritin is normal or high because it is an acute-phase reactant. Iron deficiency has low ferritin and high TIBC. Reference: Van Vranken, Evaluation of Microcytosis, AFP 2010 (aafp.org/pubs/afp/issues/2010/1101/p1117.html).', '["That is iron deficiency.","Hepcidin traps iron in stores, so ferritin stays normal or high.","That fits iron overload.","Not a typical pattern."]'::jsonb, 2, 'verified'
