select null, t.id, 'builtin', 'The Philadelphia chromosome, t(9;22) with BCR-ABL1, is the hallmark of:', '["Chronic lymphocytic leukemia","Chronic myeloid leukemia","Acute promyelocytic leukemia","Hodgkin lymphoma"]'::jsonb, 1, 'The Philadelphia chromosome, a reciprocal translocation of chromosomes 9 and 22 forming BCR-ABL1, is found in about 95% of patients with CML. Reference: Leukemia: What Primary Care Physicians Need to Know, AFP 2023 (aafp.org/pubs/afp/issues/2023/0400/leukemia.html); Leukemia: An Overview for Primary Care, AFP 2014 (aafp.org/pubs/afp/issues/2014/0501/p731.html).', '["Mature B-cell leukemia with smudge cells.","BCR-ABL1 tyrosine kinase; treated with imatinib.","Has t(15;17) PML-RARA.","Has Reed-Sternberg cells."]'::jsonb, 1, 'verified'
