insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'A leukemoid reaction is a very high white cell count (above about 50,000/uL) caused by:', '["A reactive cause outside the bone marrow, such as severe infection","Chronic myeloid leukemia","Acute lymphoblastic leukemia","Hairy cell leukemia"]'::jsonb, 0, 'A leukemoid reaction is a WBC count above about 50,000 from a cause outside the marrow, not a leukemia. Reference: Abramson & Melton, Leukocytosis: Basics of Clinical Assessment, AFP 2000 (aafp.org/pubs/afp/issues/2000/1101/p2053.html).', '["Reactive cause (infection, burns); high LAP score, no BCR-ABL1.","A true leukemia; LAP score is low.","Shows lymphoblasts.","Usually pancytopenia, not a high WBC."]'::jsonb, 2, 'verified'
