insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Pelger-Huet anomaly shows neutrophils with:', '["Giant azurophilic granules","Bilobed or non-segmented nuclei","Large blue Dohle-like inclusions","Hypersegmented nuclei"]'::jsonb, 1, 'Pelger-Huet neutrophils have dumbbell-shaped bilobed ("pince-nez") nuclei with fewer segments, from LBR gene mutations; cell function is normal. Reference: Familial Pelger-Huet Anomaly (pmc.ncbi.nlm.nih.gov/articles/PMC4925487).', '["That is Chediak-Higashi syndrome.","Inherited defect in nuclear segmentation; cells work normally.","That is May-Hegglin anomaly.","Seen in megaloblastic anemia."]'::jsonb, 2, 'verified'
