insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Glanzmann thrombasthenia is caused by a defect in:', '["GP Ib/IX/V","GP IIb/IIIa","von Willebrand factor","Factor VIII"]'::jsonb, 1, 'Glanzmann thrombasthenia is a defect of GP IIb/IIIa (alphaIIb-beta3). Aggregation fails with all agonists, while ristocetin agglutination is usually preserved. Reference: Nurden, Glanzmann thrombasthenia, Orphanet J Rare Dis 2006 (pmc.ncbi.nlm.nih.gov/articles/PMC1475837).', '["That is Bernard-Soulier syndrome.","Platelets cannot bind fibrinogen, so they do not aggregate.","That is von Willebrand disease.","That is hemophilia A."]'::jsonb, 2, 'verified'
