insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Factor XIII stabilizes a blood clot by:', '["Converting fibrinogen to fibrin","Cross-linking fibrin","Activating plasminogen","Binding platelets to collagen"]'::jsonb, 1, 'Activated factor XIII is a transglutaminase that cross-links fibrin chains, making the clot stable. Thrombin converts fibrinogen to fibrin. Reference: Factor XIII Deficiency: A Review of Biology, Testing, and Treatment (pmc.ncbi.nlm.nih.gov/articles/PMC12825037).', '["That is thrombin.","Factor XIIIa cross-links fibrin, making the clot strong.","That is tissue plasminogen activator.","That is von Willebrand factor."]'::jsonb, 2, 'verified'
