select null, t.id, 'builtin', 'D-dimer is a degradation product of:', '["Fibrinogen only","Cross-linked fibrin","Factor VIII","Plasminogen"]'::jsonb, 1, 'D-dimer is produced when plasmin digests fibrin that was cross-linked by factor XIIIa. Reference: D-dimer Testing in Pulmonary Embolism with a Focus on Potential Pitfalls (pmc.ncbi.nlm.nih.gov/articles/PMC9689068).', '["Fibrinogen breakdown gives FDPs, not D-dimer.","Made only when plasmin breaks down cross-linked fibrin.","Not a source of D-dimer.","Plasminogen is the enzyme precursor, not the target."]'::jsonb, 2, 'verified'
